import { isTauriTavernHost } from './host-detect';
import {
  normalizeCustomApiFormat,
  promptPostProcessingRequiresChatCompletion,
  type ApiConfig,
  type ApiPreset,
  type CustomApiFormat,
  type PromptPostProcessing,
} from '../tasks/schema';

export interface ApiPresetDraft {
  name: string;
  url: string;
  apiKey: string;
  model: string;
  max_tokens: number;
  temperature: number;
  bodyParams: string;
  excludeBodyParams: string;
  requestHeaders: string;
  customPromptPostProcessing: PromptPostProcessing;
  includeReasoning: boolean;
  reasoningEffort: 'low' | 'medium' | 'high';
  customApiFormat: CustomApiFormat;
}

export interface ApiPayloadOverrides {
  customPromptPostProcessing?: PromptPostProcessing;
}

export function createEmptyApiPresetDraft(): ApiPresetDraft {
  return {
    name: '',
    url: '',
    apiKey: '',
    model: '',
    max_tokens: 60000,
    temperature: 1,
    bodyParams: '',
    excludeBodyParams: '',
    requestHeaders: '',
    customPromptPostProcessing: 'none',
    includeReasoning: false,
    reasoningEffort: 'medium',
    customApiFormat: 'openai_compat',
  };
}

export function apiPresetDraftFromPreset(preset: ApiPreset): ApiPresetDraft {
  const cfg = preset.apiConfig;
  return {
    name: preset.name,
    url: cfg.url || '',
    apiKey: cfg.apiKey || '',
    model: cfg.model || '',
    max_tokens: Number(cfg.max_tokens || 60000),
    temperature: Number(cfg.temperature ?? 1),
    bodyParams: cfg.bodyParams || '',
    excludeBodyParams: cfg.excludeBodyParams || '',
    requestHeaders: cfg.requestHeaders || '',
    customPromptPostProcessing: cfg.customPromptPostProcessing ?? 'none',
    includeReasoning: cfg.includeReasoning ?? false,
    reasoningEffort: cfg.reasoningEffort ?? 'medium',
    customApiFormat: normalizeCustomApiFormat(cfg.customApiFormat),
  };
}

export function apiPresetFromDraft(draft: ApiPresetDraft): ApiPreset {
  return {
    name: draft.name.trim(),
    apiConfig: {
      url: draft.url.trim(),
      apiKey: draft.apiKey,
      model: draft.model.trim(),
      source: 'openai',
      max_tokens: Math.max(1, Math.floor(Number(draft.max_tokens) || 60000)),
      temperature: Number.isFinite(Number(draft.temperature)) ? Number(draft.temperature) : 1,
      bodyParams: draft.bodyParams || '',
      excludeBodyParams: draft.excludeBodyParams || '',
      requestHeaders: draft.requestHeaders || '',
      customPromptPostProcessing: draft.customPromptPostProcessing ?? 'none',
      includeReasoning: draft.includeReasoning ?? false,
      reasoningEffort: draft.reasoningEffort ?? 'medium',
      customApiFormat: normalizeCustomApiFormat(draft.customApiFormat),
    },
  };
}

export function presetMetaLabel(preset: ApiPreset): string {
  return preset.apiConfig.model || '自定义 API';
}

export function normalizeExcludeBodyParams(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return '';
  if (trimmed.startsWith('- ') || trimmed.startsWith('[') || trimmed.startsWith('{')) return trimmed;
  return trimmed
    .split(/[,\n]/)
    .map(s => s.trim())
    .filter(Boolean)
    .map(key => `- ${key}`)
    .join('\n');
}

export function buildCustomApiHeaders(apiKey: string, requestHeaders: string): string {
  let headers = apiKey ? `Authorization: Bearer ${apiKey}` : '';
  const extra = requestHeaders.trim();
  if (extra) headers = headers ? `${headers}\n${extra}` : extra;
  return headers;
}

/** 附加主体、排除参数或请求头。不含提示词后处理，供设置页警告使用。 */
export function hasCustomRequestFields(
  apiConfig: Pick<ApiConfig, 'bodyParams' | 'excludeBodyParams' | 'requestHeaders'>,
): boolean {
  return Boolean(apiConfig.bodyParams?.trim() || apiConfig.excludeBodyParams?.trim() || apiConfig.requestHeaders?.trim());
}

export function hasApiBodyExtras(apiConfig: ApiConfig): boolean {
  return (
    hasCustomRequestFields(apiConfig) ||
    promptPostProcessingRequiresChatCompletion(apiConfig.customPromptPostProcessing)
  );
}

export function buildCustomApiFromConfig(apiConfig: ApiConfig): CustomApiConfig {
  const custom_api: CustomApiConfig = {};
  if (apiConfig.proxy_preset) custom_api.proxy_preset = apiConfig.proxy_preset;
  if (apiConfig.url) custom_api.apiurl = apiConfig.url;
  if (apiConfig.apiKey) custom_api.key = apiConfig.apiKey;
  if (apiConfig.model) custom_api.model = apiConfig.model;
  if (apiConfig.source) custom_api.source = apiConfig.source;
  if (apiConfig.max_tokens != null) custom_api.max_tokens = apiConfig.max_tokens;
  if (apiConfig.temperature != null) custom_api.temperature = apiConfig.temperature;
  return custom_api;
}

export function omitPromptLogName<T extends { name?: string }>(message: T): Omit<T, 'name'> {
  const { name: _omit, ...rest } = message;
  return rest;
}

export function omitPromptLogNames<T extends { name?: string }>(messages: T[]): Omit<T, 'name'>[] {
  return messages.map(omitPromptLogName);
}

/** 原版 SillyTavern 不识别 custom_api_format，Claude / Gemini 映射到原生源。 */
export function resolveChatCompletionSource(format: CustomApiFormat): 'custom' | 'claude' | 'makersuite' {
  if (format === 'claude_messages') return 'claude';
  if (format === 'gemini_interactions') return 'makersuite';
  return 'custom';
}

export function usesNativeChatCompletionSource(format: CustomApiFormat | undefined): boolean {
  const normalized = normalizeCustomApiFormat(format);
  return normalized === 'claude_messages' || normalized === 'gemini_interactions';
}

/** TauriTavern 上非兼容协议、原版上 Claude / Gemini，都不能走 generateRaw。 */
export function apiFormatDisallowsGenerateRawFallback(
  format: CustomApiFormat | undefined,
  tauriTavern: boolean,
): boolean {
  const normalized = normalizeCustomApiFormat(format);
  if (tauriTavern) return normalized !== 'openai_compat';
  return normalized === 'claude_messages' || normalized === 'gemini_interactions';
}

/** 只改当次 reverse_proxy，不改预设里保存的端点。 */
export function normalizeStNativeProxyBase(rawUrl: unknown, nativeSource: 'claude' | 'makersuite'): string {
  let base = String(rawUrl || '').trim().replace(/\/+$/, '');
  if (!base) return '';
  for (const suffix of ['/chat/completions', '/messages', '/responses', '/interactions']) {
    if (base.endsWith(suffix)) {
      base = base.slice(0, -suffix.length).replace(/\/+$/, '');
      break;
    }
  }
  if (nativeSource === 'claude') {
    if (base.endsWith('/v1beta')) base = base.slice(0, -'/v1beta'.length).replace(/\/+$/, '');
    let path = '';
    try {
      path = new URL(base).pathname.replace(/\/+$/, '');
    } catch {
      /* 非法 URL 原样交给后端 */
    }
    if (path === '' || path === '/') return `${base}/v1`;
    if (!base.endsWith('/v1')) return `${base}/v1`;
    return base;
  }
  for (const suffix of ['/v1beta', '/v1']) {
    if (base.endsWith(suffix)) {
      base = base.slice(0, -suffix.length).replace(/\/+$/, '');
      break;
    }
  }
  return base;
}

export function buildChatCompletionPayload(
  messages: { role: string; content: string; name?: string }[],
  apiConfig: ApiConfig,
  overrides?: ApiPayloadOverrides,
): Record<string, unknown> {
  const model = (apiConfig.model || '').replace(/^models\//, '');
  const customPromptPostProcessing =
    overrides?.customPromptPostProcessing ?? apiConfig.customPromptPostProcessing ?? 'none';
  const format = normalizeCustomApiFormat(apiConfig.customApiFormat);
  const tauriTavern = isTauriTavernHost();
  const chatCompletionSource = tauriTavern ? 'custom' : resolveChatCompletionSource(format);
  const nativeSource = tauriTavern || chatCompletionSource === 'custom' ? null : chatCompletionSource;
  const reverseProxy = nativeSource ? normalizeStNativeProxyBase(apiConfig.url, nativeSource) : apiConfig.url;
  return {
    messages: omitPromptLogNames(messages),
    model,
    max_tokens: apiConfig.max_tokens ?? 60000,
    temperature: apiConfig.temperature ?? 1,
    top_p: 0.95,
    stream: false,
    chat_completion_source: chatCompletionSource,
    ...(tauriTavern ? { custom_api_format: format } : {}),
    include_reasoning: apiConfig.includeReasoning ?? false,
    reasoning_effort: apiConfig.reasoningEffort ?? 'medium',
    enable_web_search: false,
    request_images: false,
    custom_prompt_post_processing: customPromptPostProcessing,
    reverse_proxy: reverseProxy,
    proxy_password: nativeSource ? apiConfig.apiKey || '' : '',
    custom_url: apiConfig.url,
    custom_include_headers: buildCustomApiHeaders(apiConfig.apiKey, apiConfig.requestHeaders || ''),
    custom_include_body: apiConfig.bodyParams || '',
    custom_exclude_body: normalizeExcludeBodyParams(apiConfig.excludeBodyParams || ''),
  };
}
